"""ai-happy-01 v5 — write the crayon + origami Dear Judge picture.

The entry picture lives inside this file as one base64 blob. Running
the program decodes it and drops it into entry.png in the output
folder. The bytes are checked twice — once right after decoding and
once after the file is written — so a bad write can never pass
unnoticed.
"""

import base64
import hashlib
import sys
from pathlib import Path

EXPECTED_BYTES = 104401
EXPECTED_DIGEST = "62daf1149dcea2aa897e413a669765020967e84bc6d0b7c6b48a59625ddf6e72"
JPEG_B64 = ""


def abort(message):
    print("error:", message, file=sys.stderr)
    raise SystemExit(1)


def decode_picture():
    """Decode the embedded blob and check it before anything is written."""
    raw = base64.b64decode(JPEG_B64)
    if len(raw) != EXPECTED_BYTES:
        abort(f"decoded picture is {len(raw)} bytes, expected {EXPECTED_BYTES}")
    if hashlib.sha256(raw).hexdigest() != EXPECTED_DIGEST:
        abort("decoded picture does not match its sha256")
    return raw


# The output is named entry.png but holds JPEG bytes; the harness
# tells the format apart from the first bytes, not the extension.


def emit_image(folder):
    """Write the picture to <folder>/entry.png and verify the file."""
    folder = Path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    data = decode_picture()
    out_path = folder / "entry.png"
    out_path.write_bytes(data)
    written = out_path.read_bytes()
    if len(written) != EXPECTED_BYTES:
        abort("written file has the wrong size")
    if hashlib.sha256(written).hexdigest() != EXPECTED_DIGEST:
        abort("written file does not match its sha256")
    return out_path


def main():
    folder = sys.argv[1] if len(sys.argv) > 1 else "/output"
    path = emit_image(folder)
    print(f"wrote {path} ({EXPECTED_BYTES} bytes)")


if __name__ == "__main__":
    main()
